parameters.jsCode:
// Parse Claude output
const response = $input.first().json;

// Claude output có thể nested theo schema khác nhau
let rawText = '';
if (response.message?.content) {
  rawText = response.message.content;
} else if (response.content) {
  rawText = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
} else if (response.text) {
  rawText = response.text;
} else {
  throw new Error('Cannot find Claude response text. Got: ' + JSON.stringify(response).substring(0, 200));
}

// Strip markdown wrapper nếu có
rawText = rawText.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  throw new Error('Claude returned invalid JSON: ' + rawText.substring(0, 300));
}

// Validate schema
if (!parsed.action_items || !Array.isArray(parsed.action_items)) {
  parsed.action_items = [];
}

// Get context from earlier nodes
const context = $('Set: Extract Context').first().json;

return {
  json: {
    ...parsed,
    meeting_title: context.meeting_title,
    meeting_date: context.meeting_date,
    attendees: context.attendees,
    action_items_count: parsed.action_items.length,
    has_actions: parsed.action_items.length > 0
  }
};

